













































































































































import Vue from 'vue';
import Component from 'vue-class-component';
import NavRubrics from '@/components/nav/NavRubrics.vue';
import { Book, BookSection, ListType, NavigationData } from '@/services/Navigation/types';
import SearchInput from '@/components/ui/SearchInput.vue';
import { Prop, Ref, Watch } from 'vue-property-decorator';
import { Route } from 'vue-router';
import NavCategory from '@/components/nav/NavCategory.vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import NavLetter from '@/components/nav/NavLetter.vue';
import Loader from '@/components/ui/Loader.vue';
import ReturnIcon from '@/assets/icons/return.svg';
import { SearchBaseOptions } from '@/services/Api/SearchService';
import NavBook from '@/components/nav/NavBook.vue';
import Helpers from '@/services/Navigation/Helpers';
import NavAuthor from '@/components/nav/NavAuthor.vue';
import { getTranslation } from '@/services/Translation';
import StringService from '@/services/StringService';
import { TranslationStrings } from '@/translations/types';
import { LANGUAGE_CODE_RUSSIAN } from '@/constants';
import CollapseListIcon from '@/assets/icons/collapse-list.svg';

@Component({
  components: {
    NavAuthor,
    NavBook,
    Loader,
    NavLetter,
    NavCategory,
    NavRubrics,
    SearchInput,
    CollapseListIcon,
    ReturnIcon
  }
})
export default class Catalog extends Vue {
  @Prop({ required: false, default: '' })
  mobileMode!: '' | 'library' | 'search-area';

  lists = {
    categories: getTranslation('filterCategories'),
    authors: getTranslation('filterAuthors'),
    books: getTranslation('filterBooks')
  };
  getTranslation = getTranslation;

  @Ref('tree')
  refTree?: HTMLDivElement;

  @Action('highlightLetterByBookSlug', { namespace: 'navigation' })
  highlightLetterByBookSlug!: Function;

  @Mutation('actualizeHighlight', { namespace: 'navigation' })
  actualizeHighlight!: Function;

  @Mutation('collapseAll', { namespace: 'navigation' })
  collapseAll!: Function;

  @Mutation('checkAll', { namespace: 'navigation' })
  checkAll!: Function;

  @Mutation('uncheckAll', { namespace: 'navigation' })
  uncheckAll!: Function;

  @Mutation('setListType', { namespace: 'navigation' })
  setListType!: Function;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  data!: NavigationData;

  @Getter('currentBook', { namespace: 'navigation' })
  currentBook?: Book;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentBookSection?: BookSection;

  @Getter('searchOptions', { namespace: 'search' })
  searchOptions!: SearchBaseOptions;

  @State('resultsCount', { namespace: 'search' })
  searchResultsCount!: number;

  @Getter('showSearchResults', { namespace: 'navigation' })
  showSearchResults?: boolean;

  @State('language', { namespace: 'navigation' })
  navLanguage?: string;

  @State('loading', { namespace: 'navigation' })
  navLoading?: boolean;

  @State('loading', { namespace: 'search' })
  searchLoading?: boolean;

  @State('advancedSearch', { namespace: 'search' })
  advancedSearch?: boolean;

  @State('listType', { namespace: 'navigation' })
  listType!: ListType;

  @State('filterQuery', { namespace: 'navigation' })
  filterQuery!: string;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  highlightScrollTimeout?: number;

  async mounted() {
    this.$el.addEventListener('wheel', this.cancelPendingHighlightScroll, { passive: true });
    this.$el.addEventListener('touchstart', this.cancelPendingHighlightScroll, { passive: true });
    this.$store.commit('navigation/setShowSearchResultsFlag', this.isSearchResultsPage);
    if (!this.mobileMode) {
      this.setListType(Helpers.parseListTypeFromUrl(this.$route.path));
    }
    await this.fetchData();
  }

  beforeDestroy() {
    this.cancelPendingHighlightScroll();
    this.$el.removeEventListener('wheel', this.cancelPendingHighlightScroll);
    this.$el.removeEventListener('touchstart', this.cancelPendingHighlightScroll);
  }

  @Watch('currentBook.id')
  @Watch('currentBookSection.id')
  async onNavigationBookSection(to: number) {
    if (to) {
      this.cancelPendingHighlightScroll();
      this.highlightScrollTimeout = window.setTimeout(this.scrollToHighlighted, 50);
    }
  }

  cancelPendingHighlightScroll() {
    if (this.highlightScrollTimeout !== undefined) {
      window.clearTimeout(this.highlightScrollTimeout);
      this.highlightScrollTimeout = undefined;
    }
  }

  @Watch('navLanguage') // if user switch language in the left sidebar
  async onNavLanguageChange(to: string, from: string) {
    if (to !== from) {
      await this.fetchData();
      if (!this.mobileMode) {
        this.$store.commit('navigation/updateFilterQuery', '');
      }
    }
  }

  @Watch('showSearchResults') // if user sent search request or switched back to catalog
  async onShowSearchResultsChange(to: boolean, from: boolean) {
    if (to !== from) {
      await this.fetchData();
    }
  }

  @Watch('$route')
  async onRouteChange(to: Route, from: Route) {
    if (this.isSearchResultsPage && this.getSearchParamsHash(from) !== this.getSearchParamsHash(to)) {
      // if search params changed and we need to refresh left column search results
      await this.fetchData();
      this.$store.commit('navigation/setShowSearchResultsFlag', true);
    }
    if (!this.mobileMode) {
      this.setListType(Helpers.parseListTypeFromUrl(to.path));
    }
    if (
      this.listType === 'books' &&
      to.params.book &&
      from.params.book !== to.params.book &&
      !this.currentBook
    ) {
      // if list type is books and book was changed and there is no book's data in the store - we assume that this book was not loaded due to book's letter was not expanded yet
      await this.highlightLetter();
    }
    this.actualizeHighlight();
  }

  @Watch('listType')
  onListTypeChange() {
    this.actualizeHighlight();
  }

  @Watch('interfaceLanguage')
  async onChangeInterfaceLang() {
    this.lists = {
      categories: getTranslation('filterCategories'),
      authors: getTranslation('filterAuthors'),
      books: getTranslation('filterBooks')
    };
  }

  get onLanguage() {
    let beforeText = '';
    let afterText = '';
    if (this.interfaceLanguage == LANGUAGE_CODE_RUSSIAN) {
      beforeText = getTranslation('books') + ' ';
    } else {
      afterText = ' ' + getTranslation('books').toLocaleLowerCase();
    }

    if (!this.navLanguage) {
      return beforeText + '' + afterText;
    }

    return (
      beforeText +
      getTranslation(`onLanguageCatalog${StringService.capitalize(
        this.navLanguage
      )}` as keyof TranslationStrings) +
      afterText
    );
  }

  get showCheckboxes() {
    if (this.mobileMode === 'library') {
      return false;
    }
    if (this.mobileMode === 'search-area') {
      return true;
    }
    return this.advancedSearch;
  }

  get isSearchResultsPage() {
    return this.$route.name === 'search-results';
  }

  get showEntriesCount() {
    return this.isSearchResultsPage && this.showSearchResults;
  }

  get filteredCategories() {
    if (this.filterQuery && this.data.filter.categoryIds) {
      return this.data.categories.filter(category => this.data.filter.categoryIds.includes(category.id));
    }
    return [];
  }

  get filteredAuthors() {
    if (this.filterQuery && this.data.filter.authorIds) {
      return this.data.authors.filter(author => this.data.filter.authorIds.includes(author.id));
    }
    return [];
  }

  get filteredBooks() {
    return this.data.filter.bookSlugs.map(slug => this.data.books[slug]).filter(book => book);
  }

  async fetchData() {
    if (!this.$store.state.navigation.language) {
      return;
    }

    const routeQuery = typeof this.$route.query.query === 'string' ? this.$route.query.query.trim() : '';
    if (this.isSearchResultsPage && this.showSearchResults && routeQuery) {
      await this.$store.dispatch('navigation/searchBooks', {
        language: this.$store.state.navigation.language,
        query: routeQuery,
        ...this.searchOptions
      });
    } else {
      if (this.isSearchResultsPage && this.showSearchResults && !routeQuery) {
        this.$store.commit('navigation/setShowSearchResultsFlag', false);
      }
      const language = this.$store.state.navigation.language;
      const cachedData = this.$store.state.navigation.data[language];
      const hasCachedCatalog =
        this.mobileMode &&
        cachedData &&
        (cachedData.categories.length ||
          cachedData.authors.length ||
          cachedData.booksAlphabet.length ||
          cachedData.authorsAlphabet.length);
      if (hasCachedCatalog) {
        this.actualizeHighlight();
        return;
      }
      await this.$store.dispatch('navigation/fetch', this.$store.state.navigation.language);
      if (this.listType === 'books' && this.$route.params.book) {
        // since initially we don't know which letter should be highlighted in the book catalog, we have to send additional request to the backend
        await this.highlightLetter();
      }
    }
  }

  async highlightLetter() {
    await this.highlightLetterByBookSlug({
      language: this.$route.params.language,
      bookSlug: this.$route.params.book
    });
  }

  getSearchParamsHash(route: Route) {
    const searchParamNames = ['query', 'searchInPoem', 'exact', 'considerDiacritics', 'equalizeWriting'];
    const result: { [key: string]: string } = {};
    Object.entries(route.query)
      .filter(([name]) => searchParamNames.includes(name))
      .forEach(([name, value]) => {
        result[name.toString()] = value.toString();
      });
    return JSON.stringify(result);
  }

  async changeListType(listType: ListType) {
    this.setListType(listType);
    await this.filter(this.filterQuery);
    this.actualizeHighlight();
  }

  async onSearch(filterQuery: string) {
    if (filterQuery.length) {
      await this.filter(filterQuery);
    } else {
      this.$store.commit('navigation/resetFilter');
    }
    this.$store.commit('navigation/updateFilterQuery', filterQuery);
    this.$forceUpdate();
  }

  async filter(filterQuery: string) {
    if (!filterQuery) {
      return;
    }
    await this.$store.dispatch('navigation/filter', {
      language: this.$store.state.navigation.language,
      query: filterQuery
    });
  }

  scrollToHighlighted() {
    this.highlightScrollTimeout = undefined;
    if (!this.refTree) {
      return;
    }
    const activeLinks = this.refTree.querySelectorAll('.router-link-active') as NodeListOf<HTMLElement>;
    const highlight = activeLinks[activeLinks.length - 1];
    const scroll = this.refTree.querySelector('.nav-catalog-tree-inner');
    if (highlight && highlight.parentElement && scroll) {
      scroll.scrollTo({
        top: highlight.parentElement.offsetTop - this.refTree.offsetHeight * 0.5,
        behavior: 'auto'
      });
    }
  }

  returnToCatalog() {
    this.$store.commit('navigation/setShowSearchResultsFlag', false);
  }
}
