






































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import NavItemLink from '@/components/nav/NavItemLink.vue';
import NavItemFolder from '@/components/nav/NavItemFolder.vue';
import { Book, Category, NavigationData } from '@/services/Navigation/types';
import NavBook from '@/components/nav/NavBook.vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import { LABEL_OFFSET_PX, LEVEL_OFFSET_PX } from '@/services/Navigation/constants';

@Component({
  name: 'NavCategory',
  components: { NavBook, NavCategory, NavItemLink, NavItemFolder }
})
export default class NavCategory extends Vue {
  @Prop({ required: true })
  category!: Category;

  @Prop({ required: false, default: 0 })
  level!: number;

  @Prop({ required: true })
  showCheckboxes!: boolean;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  navData!: NavigationData;

  @Action('fetchCategoryBooks', { namespace: 'navigation' })
  fetchCategoryBooks!: Function;

  @Mutation('toggleCategoryExpand', { namespace: 'navigation' })
  toggleCategoryExpand!: Function;

  @Action('toggleCategorySelection', { namespace: 'navigation' })
  toggleCategorySelection!: Function;

  loading: boolean = false;

  async mounted() {
    if (this.needBooksLoad) {
      await this.loadBooks();
    }
  }

  @Watch('category.expanded')
  async onCategoryExpand(to: boolean, from: boolean) {
    if (to !== from && this.needBooksLoad) {
      // if category is expanded and has books and there is no loaded books yet
      await this.loadBooks();
    }
  }

  get offset() {
    if (!this.level) {
      return LABEL_OFFSET_PX;
    }
    return this.level * LEVEL_OFFSET_PX + LABEL_OFFSET_PX;
  }

  get children() {
    const { categories } = this.navData;
    if (this.category.is_parent) {
      return categories.filter(category => category.parent_id === this.category.id);
    }
    return [];
  }

  get books() {
    const { books } = this.navData;
    return Object.values(books).filter((book: Book) => this.category.bookIds.includes(book.id));
  }

  get needBooksLoad() {
    return this.category.expanded && this.category.is_books_exist && !this.books.length;
  }

  toggleExpand() {
    this.toggleCategoryExpand(this.category.id);
  }

  toggleCheck() {
    this.toggleCategorySelection(this.category.id);
  }

  async loadBooks() {
    this.loading = true;
    await this.fetchCategoryBooks({
      language: this.$store.state.navigation.language,
      categoryId: this.category.id
    });
    this.loading = false;
  }
}
