




































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import Checkbox from '@/components/ui/Checkbox.vue';
import Loader from '@/components/ui/Loader.vue';
import NavItemIcon from '@/components/nav/NavItemIcon.vue';
import NavItemText from '@/components/nav/NavItemText.vue';
import NavItemEntriesCount from '@/components/nav/NavItemEntriesCount.vue';
import { State } from 'vuex-class';
import { LIST_SCALE_TABLET, LIST_SCALE_AUTO } from '@/constants';

@Component({
  components: { Loader, Checkbox, NavItemIcon, NavItemText, NavItemEntriesCount }
})
export default class NavItemFolder extends Vue {
  LIST_SCALE_TABLET = LIST_SCALE_TABLET;
  LIST_SCALE_AUTO = LIST_SCALE_AUTO;

  @Prop({ required: true })
  highlight!: boolean;

  @Prop({ required: true })
  searchMatch!: boolean;

  @Prop({ required: true })
  text!: string;

  @Prop({ required: true })
  expanded!: boolean;

  @Prop({ required: true })
  offset!: number;

  @Prop({ required: true })
  primary!: boolean;

  @Prop({ required: false })
  bookIcon?: boolean;

  @Prop({ required: false })
  link?: string;

  @Prop({ required: false })
  showCheckbox?: boolean;

  @Prop({ required: false })
  checkboxChecked?: boolean;

  @Prop({ required: false })
  checkboxPartiallyChecked?: boolean;

  @Prop({ required: false })
  showEntriesCount?: boolean;

  @Prop({ required: false })
  entriesCount?: number;

  @Prop({ required: false })
  loading?: boolean;

  @State('catalogListScale', { namespace: 'reader' })
  catalogListScale!: string;

  onNavigate() {
    this.$root.$emit('reader-link-selected', { link: this.link, name: this.text });
  }
}
