




















































import Vue from 'vue';
import Component from 'vue-class-component';
import Checkbox from '@/components/ui/Checkbox.vue';
import { Mutation, State } from 'vuex-class';
import { getTranslation } from '@/services/Translation';
import { Watch } from 'vue-property-decorator';

@Component({
  components: { Checkbox }
})
export default class TextTypesFilter extends Vue {
  dragStartY: number | null = null;

  dragOffset: number = 0;

  dragging: boolean = false;

  dragPointerId: number | null = null;

  dialogTrigger: HTMLElement | null = null;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  @Mutation('switchTextTypeFilter', { namespace: 'reader' })
  switchTextTypeFilter!: Function;

  @Mutation('setTextTypesFilterVisible', { namespace: 'reader' })
  setTextTypesFilterVisible!: Function;

  textTypes = this.getTextTypes();

  getTranslation = getTranslation;

  mounted() {
    document.addEventListener('keydown', this.onDocumentKeydown);
  }

  beforeDestroy() {
    document.removeEventListener('keydown', this.onDocumentKeydown);
  }

  onDocumentKeydown(event: KeyboardEvent) {
    if (!this.visible) {
      return;
    }
    if (event.key === 'Escape') {
      this.close();
      return;
    }
    if (event.key === 'Tab') {
      this.trapFocus(event);
    }
  }

  get visible() {
    return this.$store.state.reader.isTextTypesFiltersVisible;
  }

  @Watch('visible')
  onVisibilityChange(visible: boolean) {
    if (visible) {
      const activeElement = document.activeElement;
      this.dialogTrigger =
        activeElement instanceof HTMLElement && activeElement !== document.body ? activeElement : null;
      this.$nextTick(() => {
        const dialog = this.$refs.dialog as HTMLElement;
        if (dialog) {
          window.requestAnimationFrame(() => dialog.focus());
        }
      });
      return;
    }
    this.$nextTick(() => {
      if (this.dialogTrigger && document.contains(this.dialogTrigger)) {
        this.dialogTrigger.focus();
      }
      this.dialogTrigger = null;
    });
  }

  trapFocus(event: KeyboardEvent) {
    const dialog = this.$refs.dialog as HTMLElement;
    if (!dialog) {
      return;
    }
    const focusable = Array.from(
      dialog.querySelectorAll<HTMLElement>(
        'button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'
      )
    ).filter(element => element.offsetParent !== null);
    if (!focusable.length) {
      event.preventDefault();
      dialog.focus();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }

  getTextTypes() {
    return [
      { code: 'sanskrit', name: getTranslation('sanskrit') },
      { code: 'diacritic', name: getTranslation('diacritic') },
      { code: 'word-by-word', name: getTranslation('wordByWordTranslation') },
      { code: 'translate', name: getTranslation('translation') },
      { code: 'comment', name: getTranslation('comment') }
    ];
  }

  close() {
    this.dragStartY = null;
    this.dragOffset = 0;
    this.dragging = false;
    this.dragPointerId = null;
    this.setTextTypesFilterVisible(false);
  }

  startDrag(event: PointerEvent) {
    const target = event.target as HTMLElement;
    if (target.closest('button')) {
      return;
    }
    this.dragPointerId = event.pointerId;
    this.dragStartY = event.clientY;
    this.dragging = true;
    const dragRegion = event.currentTarget as HTMLElement;
    if (dragRegion.setPointerCapture) {
      dragRegion.setPointerCapture(event.pointerId);
    }
  }

  moveDrag(event: PointerEvent) {
    if (this.dragStartY === null || this.dragPointerId !== event.pointerId) {
      return;
    }
    this.dragOffset = Math.max(0, event.clientY - this.dragStartY);
    if (this.dragOffset > 0 && event.cancelable) {
      event.preventDefault();
    }
  }

  endDrag(event: PointerEvent) {
    if (this.dragPointerId !== event.pointerId) {
      return;
    }
    const dragRegion = event.currentTarget as HTMLElement;
    if (
      dragRegion.releasePointerCapture &&
      dragRegion.hasPointerCapture &&
      dragRegion.hasPointerCapture(event.pointerId)
    ) {
      dragRegion.releasePointerCapture(event.pointerId);
    }
    if (this.dragOffset >= 64) {
      this.close();
      return;
    }
    this.dragStartY = null;
    this.dragOffset = 0;
    this.dragging = false;
    this.dragPointerId = null;
  }

  cancelDrag() {
    this.dragStartY = null;
    this.dragOffset = 0;
    this.dragging = false;
    this.dragPointerId = null;
  }

  @Watch('interfaceLanguage')
  onChangeInterfaceLang() {
    this.textTypes = this.getTextTypes();
  }
}
