





















import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import IconLibrary from '@/assets/icons/nav-book.svg';
import IconSearch from '@/assets/icons/zoom.svg';
import IconBookmark from '@/assets/icons/bookmark-nav.svg';
import IconSettings from '@/assets/icons/settings.svg';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { IconLibrary, IconSearch, IconBookmark, IconSettings }
})
export default class MobileNavigation extends Vue {
  @Prop({ required: true })
  active!: string;

  getTranslation = getTranslation;

  items = this.getItems();

  @Watch('$store.state.reader.interfaceLanguage')
  onInterfaceLanguageChange() {
    this.items = this.getItems();
  }

  getItems() {
    return [
      { code: 'library', label: getTranslation('library'), icon: IconLibrary },
      { code: 'search', label: getTranslation('search'), icon: IconSearch },
      { code: 'bookmarks', label: getTranslation('bookmarks'), icon: IconBookmark },
      { code: 'settings', label: getTranslation('settings'), icon: IconSettings }
    ];
  }
}
