















import Vue from 'vue';
import Component from 'vue-class-component';
import UrlBuilderService from '@/services/UrlBuilderService';
import SearchService from '@/services/Api/SearchService';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';
import { getTranslation } from '@/services/Translation';
import { State } from 'vuex-class';

@Component
export default class SearchHistory extends Vue {
  list: Array<{ query: string; url: string }> = [];

  error: boolean = false;

  loaded: boolean = false;

  getTranslation = getTranslation;

  @State('language', { namespace: 'navigation' })
  navigationLanguage!: string;

  async mounted() {
    this.list = [];
    this.error = false;
    try {
      const response: Array<{ query: string }> = await SearchService.getSearchHistory();
      if (response && response.length) {
        this.list = this.prepareList(response);
      }
    } catch (e) {
      this.error = true;
    } finally {
      this.loaded = true;
      this.$emit('state-change', this.list.length > 0);
    }
  }

  async clearSearchHistory() {
    this.list = [];
    this.error = false;
    try {
      const response = await SearchService.clearSearchHistory();
      if (response && response.length) {
        this.list = this.prepareList(response);
      }
      this.$emit('state-change', this.list.length > 0);
      this.$emit('cleared');
    } catch (e) {
      this.error = true;
    }
  }

  prepareList(list: Array<{ query: string }>) {
    const language = this.$route.params.language || this.navigationLanguage || LANGUAGE_CODE_DEFAULT;
    return list.map(item => ({
      ...item,
      url: UrlBuilderService.getSearchQueryUrl({ language, query: item.query })
    }));
  }
}
