



















































import Vue from 'vue';
import Component from 'vue-class-component';
import { Ref, Watch } from 'vue-property-decorator';
import UrlBuilderService from '@/services/UrlBuilderService';
import Loader from '@/components/ui/Loader.vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import { Book, BookSection, Category } from '@/services/Navigation/types';
import ArrayService from '@/services/ArrayService';
import { SearchItem } from '@/services/Api/SearchService';
import SearchPriorityBook from '@/components/SearchPriorityBook.vue';
import SearchPriorityAuthor from '@/components/SearchPriorityAuthor.vue';
import SearchPriorityBookSection from '@/components/SearchPriorityBookSection.vue';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { SearchPriorityBookSection, SearchPriorityAuthor, SearchPriorityBook, Loader }
})
export default class SearchResults extends Vue {
  loadingMore = false;
  perPage = 50;
  page = 1;
  getSearchItemUrl = UrlBuilderService.getSearchResultItemUrl;

  getTranslation = getTranslation;

  get hasQuery() {
    return typeof this.$route.query.query === 'string' && !!this.$route.query.query.trim();
  }

  get priorityBooks() {
    const book = this.searchPriorityResults && (this.searchPriorityResults as any).book;
    if (!book) {
      return [];
    }
    return Array.isArray(book) ? book : [book];
  }

  @Ref('scroll')
  refScroll!: HTMLDivElement;

  @Ref('searchResults')
  refSearchResults?: HTMLDivElement;

  @State('results', { namespace: 'search' })
  searchResults!: Array<SearchItem>;

  @State('resultsCount', { namespace: 'search' })
  searchResultsCount!: number;

  @State('priorityResults', { namespace: 'search' })
  searchPriorityResults!: {};

  @State('needUpdate', { namespace: 'search' })
  searchNeedUpdate?: Array<SearchItem>;

  @State('loading', { namespace: 'search' })
  searchLoading?: boolean;

  @State('error', { namespace: 'search' })
  searchError?: boolean;

  @State('loading', { namespace: 'navigation' })
  navLoading?: boolean;

  @State('scale', { namespace: 'reader' })
  scale!: number;

  @Getter('showSearchResults', { namespace: 'navigation' })
  navShowSearchResults?: boolean;

  @Getter('checkedCategories', { namespace: 'navigation' })
  checkedCategories!: Array<Category>;

  @Getter('checkedBooks', { namespace: 'navigation' })
  checkedBooks!: Array<Book>;

  @Getter('checkedBookSections', { namespace: 'navigation' })
  checkedBookSections!: Array<BookSection>;

  @Getter('checkedFoundBooks', { namespace: 'navigation' })
  checkedFoundBooks!: Array<Book>;

  @Getter('checkedFoundBookSections', { namespace: 'navigation' })
  checkedFoundBookSections!: Array<BookSection>;

  @Action('fetchResults', { namespace: 'search' })
  doFetchResults!: Function;

  @Mutation('updateActiveTabName', { namespace: 'tabs' })
  updateActiveTabName!: Function;

  @Mutation('setShowSearchResultsFlag', { namespace: 'navigation' })
  setShowSearchResultsFlag!: Function;

  async mounted() {
    this.refScroll.addEventListener('scroll', this.onScroll);
  }

  @Watch('searchNeedUpdate')
  async onSearchNeedUpdate(to: boolean, from: boolean) {
    if (to !== from && to) {
      this.updateTabName();
      await this.fetchResults();
    }
  }

  @Watch('checkedFoundBooks')
  @Watch('checkedFoundBookSections')
  async onCheckedChange(to: Array<any>, from: Array<any>) {
    if (
      ArrayService.makeHashFromIds(to) !== ArrayService.makeHashFromIds(from) &&
      this.navShowSearchResults
    ) {
      await this.fetchResults();
    }
  }

  async fetchResults() {
    this.setShowSearchResultsFlag(true);
    await this.doFetchResults({ offset: 0, perPage: this.perPage });
  }

  async fetchMore() {
    this.loadingMore = true;
    this.page += 1;
    await this.doFetchResults({ offset: this.perPage * (this.page - 1), perPage: this.perPage });
    this.loadingMore = false;
  }

  updateTabName() {
    this.updateActiveTabName(this.$route.query.query);
  }

  async onScroll() {
    if (!this.refSearchResults) {
      return;
    }
    const isScrolledToBottom =
      this.refScroll.offsetHeight + this.refScroll.scrollTop >= this.refSearchResults.offsetHeight;
    if (!isScrolledToBottom || this.searchLoading || this.loadingMore) {
      return;
    }
    const hasMorePages = this.searchResultsCount > 0 && this.searchResults.length < this.searchResultsCount;
    if (hasMorePages) {
      await this.fetchMore();
    }
  }
}
