import { Author, Book, BookSection, Category, NavigationData } from '@/services/Navigation/types';
import Helpers from '@/services/Navigation/Helpers';
import SearchScopeService from '@/services/SearchScopeService';

type CheckableNavEntity = Book | BookSection | Category | Author;

export default class CheckService {
  public static checkAll({ books, categories, authors, foundBooks, ...rest }: NavigationData) {
    let checkedBooks = Helpers.checkBooks(books);
    checkedBooks = Helpers.checkBookSections(checkedBooks);
    let checkedFoundBooks = Helpers.checkBooks(foundBooks);
    checkedFoundBooks = Helpers.checkBookSections(checkedFoundBooks);
    return {
      ...rest,
      books: checkedBooks,
      foundBooks: checkedFoundBooks,
      categories: Helpers.checkAll(categories),
      authors: Helpers.checkAll(authors)
    };
  }

  public static uncheckAll({ books, categories, authors, foundBooks, ...rest }: NavigationData) {
    let uncheckedBooks = Helpers.uncheckBooks(books);
    uncheckedBooks = Helpers.uncheckBookSections(uncheckedBooks);
    let uncheckedFoundBooks = Helpers.uncheckBooks(foundBooks);
    uncheckedFoundBooks = Helpers.uncheckBookSections(uncheckedFoundBooks);
    return {
      ...rest,
      books: uncheckedBooks,
      foundBooks: uncheckedFoundBooks,
      categories: Helpers.uncheckAll(categories),
      authors: Helpers.uncheckAll(authors)
    };
  }

  public static toggleCategoryCheck(navigation: NavigationData, categoryId: number) {
    const categoryIndex = navigation.categories.findIndex(category => category.id === categoryId);
    const category = navigation.categories[categoryIndex];
    const checked = !category.checked;
    const branchCategoryIds = SearchScopeService.getBranchCategoryIds(navigation.categories, categoryId);
    const branchBookIds = new Set<number>();

    navigation.categories.forEach(branchCategory => {
      if (!branchCategoryIds.has(Number(branchCategory.id))) {
        return;
      }
      branchCategory.checked = checked;
      branchCategory.partiallyChecked = false;
      branchCategory.bookIds.forEach(bookId => branchBookIds.add(Number(bookId)));
    });

    Object.values(navigation.books).forEach(book => {
      if (!branchBookIds.has(Number(book.id))) {
        return;
      }
      book.checked = checked;
      book.partiallyChecked = false;
      book.children = book.children.map(bookSection => ({
        ...bookSection,
        checked,
        partiallyChecked: false
      }));
    });

    CheckService.actualizeParentCategories(navigation, categoryIndex);
  }

  public static toggleBookCheck(navigation: NavigationData, bookSlug: string) {
    const book = navigation.books[bookSlug];
    const checked = !book.checked;

    // 1. Toggle clicked book's flag
    navigation.books[bookSlug].partiallyChecked = false;
    navigation.books[bookSlug].checked = checked;

    // 2. Iterate over all children BookSections and check them.
    navigation.books[bookSlug].children = navigation.books[bookSlug].children.map(bookSection =>
      !bookSection.parentId ? { ...bookSection, checked, partiallyChecked: false } : bookSection
    );

    // 3. Actualize Category's `checked` / `partiallyChecked` flags.
    const categoryIndex = navigation.categories.findIndex(category => category.bookIds.includes(book.id));
    CheckService.actualizeCategory(navigation, categoryIndex);

    // 4.Iterate over all parent Categories and actualize `checked` / `partiallyChecked` flags.
    CheckService.actualizeParentCategories(navigation, categoryIndex);
  }

  public static toggleFoundBookCheck(navigation: NavigationData, bookSlug: string) {
    const book = navigation.foundBooks[bookSlug];
    const checked = !book.checked;

    // 1. Toggle clicked book's flag
    navigation.foundBooks[bookSlug].partiallyChecked = false;
    navigation.foundBooks[bookSlug].checked = checked;

    // 2. Iterate over all children BookSections and check them.
    navigation.foundBooks[bookSlug].children = navigation.foundBooks[bookSlug].children.map(bookSection => ({
      ...bookSection,
      checked,
      partiallyChecked: false
    }));
  }

  public static toggleBookSectionCheck(navigation: NavigationData, bookSectionId: string, bookSlug: string) {
    const book = navigation.books[bookSlug];
    const bookSectionIndex = book.children.findIndex(bookSection => bookSection.id === bookSectionId);
    const bookSection = navigation.books[bookSlug].children[bookSectionIndex];
    const checked = !bookSection.checked;

    // 1. Toggle clicked bookSection's flag
    navigation.books[bookSlug].children[bookSectionIndex].partiallyChecked = false;
    navigation.books[bookSlug].children[bookSectionIndex].checked = checked;

    // 2. Iterate over all children BookSections and check / uncheck them.
    Helpers.updateChildren(navigation.books[bookSlug].children, bookSectionIndex, item => ({
      ...item,
      checked,
      partiallyChecked: false
    }));

    // 3. Iterate over all parent BookSections and actualize `checked` / `partiallyChecked` flags.
    Helpers.updateParents(navigation.books[bookSlug].children, bookSectionIndex, childBookSection => {
      // find exact children of the bookSection (no sub-children)
      const children = book.children.filter(child => child.parentId === childBookSection.id);
      // find checked children amount and compare with amount of all children
      return CheckService.actualizeEntryFlags(childBookSection as BookSection, children);
    });

    // 4.  Actualize Book's `checked` / `partiallyChecked` flags.
    const bookSections = book.children.filter(
      childBookSection => !childBookSection.parentId && childBookSection.is_parent
    );
    CheckService.actualizeEntryFlags(navigation.books[bookSlug], bookSections);

    const categoryIndex = navigation.categories.findIndex(category => category.bookIds.includes(book.id));
    if (categoryIndex >= 0) {
      // 5. Actualize Category's `checked` / `partiallyChecked` flags.
      this.actualizeCategory(navigation, categoryIndex);

      // 6. Iterate over all parent Categories and actualize `checked` / `partiallyChecked` flags.
      this.actualizeParentCategories(navigation, categoryIndex);
    }
  }

  public static toggleFoundBookSectionCheck(
    navigation: NavigationData,
    bookSectionId: string,
    bookSlug: string
  ) {
    const book = navigation.foundBooks[bookSlug];
    const bookSectionIndex = book.children.findIndex(bookSection => bookSection.id === bookSectionId);
    const bookSection = navigation.foundBooks[bookSlug].children[bookSectionIndex];
    const checked = !bookSection.checked;

    // 1. Toggle clicked bookSection's flag
    navigation.foundBooks[bookSlug].children[bookSectionIndex].partiallyChecked = false;
    navigation.foundBooks[bookSlug].children[bookSectionIndex].checked = checked;

    // 2. Iterate over all children BookSections and check / uncheck them.
    Helpers.updateChildren(navigation.foundBooks[bookSlug].children, bookSectionIndex, item => ({
      ...item,
      checked,
      partiallyChecked: false
    }));

    // 3. Iterate over all parent BookSections and actualize `checked` / `partiallyChecked` flags.
    Helpers.updateParents(navigation.foundBooks[bookSlug].children, bookSectionIndex, childBookSection => {
      // find exact children of the bookSection (no sub-children)
      const children = book.children.filter(child => child.parentId === childBookSection.id);
      // find checked children amount and compare with amount of all children
      return CheckService.actualizeEntryFlags(childBookSection as BookSection, children);
    });

    // 4.  Actualize Book's `checked` / `partiallyChecked` flags.
    const bookSections = book.children.filter(
      childBookSection => !childBookSection.parentId && childBookSection.is_parent
    );
    CheckService.actualizeEntryFlags(navigation.foundBooks[bookSlug], bookSections);
  }

  private static actualizeCategory(navigation: NavigationData, categoryIndex: number) {
    if (categoryIndex < 0) {
      return;
    }
    const categoryBookIds = navigation.categories[categoryIndex].bookIds;
    const categoryBooks = Object.values(navigation.books).filter(book => categoryBookIds.includes(book.id));
    const children = navigation.categories.filter(
      childCategory => childCategory.parent_id === navigation.categories[categoryIndex].id
    );
    CheckService.actualizeEntryFlags(navigation.categories[categoryIndex], [...children, ...categoryBooks]);
  }

  private static actualizeParentCategories(navigation: NavigationData, categoryIndex: number) {
    if (categoryIndex < 0) {
      return;
    }
    Helpers.updateParents(navigation.categories, categoryIndex, category => {
      // find exact children and books of the category (no sub-children)
      const categoryBooks = Object.values(navigation.books).filter(book =>
        category.bookIds.includes(book.id)
      );
      const children = navigation.categories.filter(childCategory => childCategory.parent_id === category.id);
      return CheckService.actualizeEntryFlags(category as Category, [...children, ...categoryBooks]);
    });
  }

  private static actualizeEntryFlags(entity: CheckableNavEntity, children: Array<CheckableNavEntity>) {
    const checkedChildren = children.filter(child => child.checked);
    const partiallyCheckedChildren = children.filter(child => child.partiallyChecked);
    entity.checked = checkedChildren.length === children.length;
    entity.partiallyChecked =
      (checkedChildren.length > 0 && checkedChildren.length < children.length) ||
      partiallyCheckedChildren.length > 0;
    return entity;
  }
}
