import { store } from '@/store';
import { ApiService } from '@/services/Api/ApiService';
import { endpoints } from '@/api-endpoints.json';
import { Author } from '@/services/Api/AuthorsService/Author.types';

export default class AuthorsService {
  private static instance: AuthorsService;

  apiService: ApiService = new ApiService();

  private static getInstance() {
    if (!AuthorsService.instance) {
      AuthorsService.instance = new AuthorsService();
    }
    return AuthorsService.instance;
  }

  static async getAuthor(lang: string, slug: string): Promise<Author> {
    const instance = this.getInstance();
    return instance.apiService
      .setEndpoint(endpoints.author.replace(':lang', lang).replace(':slug', slug))
      .setToken(store.state.auth.token)
      .cache()
      .get()
      .then(response => response.data.data);
  }
}
