




import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import { State } from 'vuex-class';
import StringService from '@/services/StringService';

@Component
export default class NavItemText extends Vue {
  @Prop({ required: true })
  text!: string;

  @State('filterQuery', { namespace: 'navigation' })
  filterQuery!: string;

  get textFormatted() {
    if (this.filterQuery) {
      let re = this.filterQuery;
      // russian diacritic
      re = StringService.replaceAll(re, 'а', '[аā]');
      re = StringService.replaceAll(re, 'р', '[р]');
      re = StringService.replaceAll(re, 'у', '[yӯ]');
      re = StringService.replaceAll(re, 'и', '[иӣ]');
      re = StringService.replaceAll(re, 'д', '[д]');
      re = StringService.replaceAll(re, 'т', '[т]');
      re = StringService.replaceAll(re, 'н', '[н]');
      re = StringService.replaceAll(re, 'х', '[х]');
      re = StringService.replaceAll(re, 'х', '[н]');
      re = StringService.replaceAll(re, 'л', '[л]');
      re = StringService.replaceAll(re, 'ш', '[ш]');
      re = StringService.replaceAll(re, 'м', '[м]');
      // eng diacritic
      re = StringService.replaceAll(re, 's', '[s|ṣ|ś]');
      re = StringService.replaceAll(re, 'r', '[ṝṛr]');
      re = StringService.replaceAll(re, 'u', '[ūu]');
      re = StringService.replaceAll(re, 'i', '[īi]');
      re = StringService.replaceAll(re, 'a', '[āa]');
      re = StringService.replaceAll(re, 'd', '[dḍ]');
      re = StringService.replaceAll(re, 't', '[ṭt]');
      re = StringService.replaceAll(re, 'n', '[nṅñṇ]');
      re = StringService.replaceAll(re, 'h', '[ḥh]');
      re = StringService.replaceAll(re, 'l', '[lḷỿḹ]');
      re = StringService.replaceAll(re, 'm', '[mṁḿ]');

      return this.text.replace(new RegExp(`(${re})`, 'ig'), '<b>$1</b>');
    }
    return this.text;
  }
}
