export function getCookieDomain(hostname: string = window.location.hostname): string {
  const sharedRootDomain = 'vedarama.ru';
  if (hostname === sharedRootDomain || hostname.endsWith(`.${sharedRootDomain}`)) {
    return `.${sharedRootDomain}`;
  }
  return '';
}

class CookieService {
  get(name: string): string | null {
    const match = document.cookie.match(
      new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()[\]\\/+^])/g, '\\$1') + '=([^;]*)')
    );
    return match ? decodeURIComponent(match[1]) : null;
  }

  set(name: string, value: string, days: number = 365) {
    const domain = getCookieDomain();
    const domainAttribute = domain ? `; domain=${domain}` : '';
    const expires = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toUTCString();
    const secure = window.location.protocol === 'https:' ? '; Secure' : '';
    document.cookie = `${name}=${encodeURIComponent(
      value
    )}; path=/${domainAttribute}; expires=${expires}; SameSite=None${secure}`;
  }

  remove(name: string) {
    const domain = getCookieDomain();
    const domainAttribute = domain ? `; domain=${domain}` : '';
    const secure = window.location.protocol === 'https:' ? '; Secure' : '';
    document.cookie = `${name}=; path=/${domainAttribute}; expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=None${secure}`;
  }
}

export default new CookieService();
