











































































































































































































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Getter, Mutation, State } from 'vuex-class';
import { Prop, Watch } from 'vue-property-decorator';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';
import router from '@/router';
import IconBook from '@/assets/icons/book.svg';
import IconSearchSettings from '@/assets/icons/search-settings.svg';
import IconHistory from '@/assets/icons/history.svg';
import IconArrowSearchLeft from '@/assets/icons/arrow-search-left.svg';
import IconArrowSearchRight from '@/assets/icons/arrow-search-right.svg';
import IconList from '@/assets/icons/list.svg';
import IconReturn from '@/assets/icons/return.svg';
import Checkbox from '@/components/ui/Checkbox.vue';
import SearchInput from '@/components/ui/SearchInput.vue';
import AccordionControl from '@/components/ui/AccordionControl.vue';
import AccordionContent from '@/components/ui/AccordionContent.vue';
import { Book, BookSection, Category } from '@/services/Navigation/types';
import SearchService, { SearchItem } from '@/services/Api/SearchService';
import UrlBuilderService from '@/services/UrlBuilderService';
import Overlay from '@/components/ui/Overlay.vue';
import SearchHistory from '@/components/SearchHistory.vue';
import { getTranslation } from '@/services/Translation';

@Component({
  components: {
    SearchHistory,
    AccordionControl,
    AccordionContent,
    Checkbox,
    SearchInput,
    IconBook,
    IconSearchSettings,
    IconHistory,
    IconArrowSearchLeft,
    IconArrowSearchRight,
    IconList,
    IconReturn,
    Overlay
  }
})
export default class Search extends Vue {
  @Prop({ required: false, default: false })
  mobileVisible!: boolean;

  @Prop({ required: false, default: false })
  mobileBookSearch!: boolean;

  @Prop({ required: false, default: '' })
  mobileBookName!: string;

  showHelp: boolean = false;

  showSearchHistoryOverlay: boolean = false;

  hasSearchHistory: boolean = false;

  searchQuery: string | null = null; // null means it is not initialised

  searchInPoem: boolean | null = null; // null means it is not initialised

  exact: boolean | null = null; // null means it is not initialised

  considerDiacritics: boolean | null = null; // null means it is not initialised

  equalizeWriting: boolean | null = null; // null means it is not initialised

  mobileSheetDragStartY: number | null = null;

  mobileSheetDragOffset: number = 0;

  mobileSheetDragging: boolean = false;

  mobileSheetPointerId: number | null = null;

  mobilePanelTrigger: HTMLElement | null = null;

  mobileSheetCloseTimer: number | null = null;

  mobileSheetLayerVisible: boolean = false;

  advancedSearchPanelVisible: boolean = false;

  getTranslation = getTranslation;

  @State('results', { namespace: 'search' })
  searchResults!: Array<SearchItem>;

  @State('inBookSearch', { namespace: 'search' })
  inBookSearch!: boolean;

  @State('advancedSearch', { namespace: 'search' })
  advancedSearch!: boolean;

  @State('readMode', { namespace: 'reader' })
  readMode!: boolean;

  @State('language', { namespace: 'navigation' })
  navLanguage!: string;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  @Getter('currentBook', { namespace: 'navigation' })
  currentBook?: Book;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentBookSection?: BookSection;

  @Getter('checkedBooks', { namespace: 'navigation' })
  checkedBooks!: Array<Book>;

  @Getter('checkedCategories', { namespace: 'navigation' })
  checkedCategories!: Array<Category>;

  @Getter('selectedBooksCount', { namespace: 'navigation' })
  selectedBooksCount!: number;

  @Mutation('setReadMode', { namespace: 'reader' })
  setReadMode!: Function;

  @Mutation('setInBookSearch', { namespace: 'search' })
  setInBookSearch!: Function;

  @Mutation('setNeedUpdate', { namespace: 'search' })
  setNeedUpdate!: Function;

  @Mutation('setResults', { namespace: 'search' })
  setResults!: Function;

  @Mutation('setResultsCount', { namespace: 'search' })
  setResultsCount!: Function;

  @Mutation('setPriorityResults', { namespace: 'search' })
  setPriorityResults!: Function;

  @Mutation('setAdvancedSearch', { namespace: 'search' })
  setAdvancedSearch!: Function;

  @Mutation('setShowSearchResultsFlag', { namespace: 'navigation' })
  setShowSearchResultsFlag!: Function;

  mounted() {
    this.actualizeSearchParams(); // initialize search params
    this.actualizeShowAdvancedSearch(); // and actualize show-advanced-search flag
    document.addEventListener('keydown', this.onDocumentKeydown);
    this.syncMobileSheetDocumentState();
    this.refreshSearchHistoryAvailability();
  }

  beforeDestroy() {
    document.removeEventListener('keydown', this.onDocumentKeydown);
    if (this.mobileSheetCloseTimer !== null) {
      window.clearTimeout(this.mobileSheetCloseTimer);
    }
    document.documentElement.classList.remove('mobile-search-sheet-open', 'mobile-search-history-open');
    this.$emit('mobile-overlay-change', false);
  }

  @Watch('$route')
  onRouteChange(to: any, from?: any) {
    this.actualizeSearchParams();
    this.actualizeShowAdvancedSearch();
    const languageChanged = Boolean(
      from && to && to.params && from.params && to.params.language !== from.params.language
    );
    if (
      languageChanged &&
      to.name === 'search-results' &&
      typeof to.query.query === 'string' &&
      to.query.query.trim()
    ) {
      this.setResults([]);
      this.setResultsCount(0);
      this.setPriorityResults(null);
      this.setNeedUpdate(true);
    }
  }

  @Watch('searchQuery')
  @Watch('searchInPoem')
  @Watch('exact')
  @Watch('considerDiacritics')
  @Watch('equalizeWriting')
  async onChangeParams(to: string | boolean, from: string | boolean | null) {
    if (this.$route.name === 'search-results' && from !== null) {
      await this.updateUrl();
    }
  }

  @Watch('advancedSearchPanelVisible')
  @Watch('showHelp')
  onMobileSheetVisibilityChange() {
    this.syncMobileSheetDocumentState();
  }

  @Watch('showSearchHistoryOverlay')
  onSearchHistoryVisibilityChange(visible: boolean) {
    document.documentElement.classList.toggle('mobile-search-history-open', this.mobileVisible && visible);
    this.emitMobileOverlayState();
  }

  @Watch('mobileVisible')
  onMobileVisibilityChange(visible: boolean) {
    if (visible) {
      this.refreshSearchHistoryAvailability();
    } else {
      this.closeSearchHistory();
    }
    this.syncMobileSheetDocumentState();
  }

  get isSearchResultPage() {
    const { index } = this.$route.query;
    return typeof index === 'string';
  }

  get currentSearchResultIndex() {
    const { index } = this.$route.query;
    if (typeof index === 'string') {
      return parseInt(index, 10);
    }
    return null;
  }

  get prevSearchResultUrl() {
    if (this.currentSearchResultIndex === null) {
      return '';
    }
    const index = this.currentSearchResultIndex - 1;
    const searchItem = this.searchResults[index];
    if (!searchItem) {
      return '';
    }
    return UrlBuilderService.getSearchResultItemUrl(searchItem, index);
  }

  get nextSearchResultUrl() {
    if (this.currentSearchResultIndex === null) {
      return '';
    }
    const index = this.currentSearchResultIndex + 1;
    const searchItem = this.searchResults[index];
    if (!searchItem) {
      return '';
    }
    return UrlBuilderService.getSearchResultItemUrl(searchItem, index);
  }

  get searchListUrl() {
    const query = new URLSearchParams();
    const searchLanguage =
      typeof this.$route.query.searchLanguage === 'string'
        ? this.$route.query.searchLanguage
        : this.$route.params.language;
    Object.entries(this.$route.query).forEach(([name, value]) => {
      if (
        !['index', 'highlight', 'reading', 'scope', 'searchLanguage'].includes(name) &&
        typeof value === 'string'
      ) {
        query.set(name, value);
      }
    });
    return `/${searchLanguage}/search?${query.toString()}`;
  }

  get editUrl() {
    if (!(this.currentBook && this.currentBookSection)) {
      return '';
    }
    return this.currentBook.edit_link.replace('{index}', this.currentBookSection.index.toString());
  }

  get mobileSheetStyle() {
    return this.mobileSheetDragOffset
      ? { transform: `translate(-50%, ${this.mobileSheetDragOffset}px)` }
      : undefined;
  }

  get advancedSearchPanelExpanded() {
    return this.mobileVisible ? this.advancedSearchPanelVisible : this.advancedSearch;
  }

  get searchBookSlug() {
    if (this.mobileVisible && !this.mobileBookSearch) {
      return '';
    }
    return this.currentBook ? this.currentBook.slug : (this.$route.query.slug as string) || '';
  }

  get searchBookId() {
    if (this.mobileVisible && !this.mobileBookSearch) {
      return undefined;
    }
    if (this.currentBook && this.currentBook.slug === this.searchBookSlug) {
      return this.currentBook.id;
    }
    const routeBookId = this.$route.query.bookId;
    if (typeof routeBookId !== 'string') {
      return undefined;
    }
    const parsedBookId = parseInt(routeBookId, 10);
    return parsedBookId > 0 ? parsedBookId : undefined;
  }

  actualizeSearchParams() {
    this.searchQuery = (this.$route.query.query || '') as string;
    this.searchInPoem = this.$route.query.searchInPoem === '1';
    this.exact = this.$route.query.exact === '1';
    this.considerDiacritics = this.$route.query.considerDiacritics === '1';
    this.equalizeWriting = this.$route.query.equalizeWriting === '1';
    if (this.$route.name === 'search-results') {
      const compactViewport = typeof window !== 'undefined' && window.innerWidth <= 1024;
      const requestedMobileBookSearch = this.$route.query.bookSearch === '1';
      const hasBookSlug = typeof this.$route.query.slug === 'string';
      const mobileBookSearchRoute = compactViewport && requestedMobileBookSearch && hasBookSlug;
      this.setInBookSearch(
        this.mobileBookSearch ||
          mobileBookSearchRoute ||
          (!compactViewport && this.$route.query.inBookOnly === '1')
      );
    }
  }

  async onSearchSubmit(searchQuery: string) {
    this.searchQuery = searchQuery;
    if (searchQuery.trim()) {
      this.hasSearchHistory = true;
    }
    await this.updateUrl();
  }

  async refreshSearchHistoryAvailability() {
    if (!this.mobileVisible) {
      return;
    }
    try {
      const history = await SearchService.getSearchHistory();
      this.hasSearchHistory = Array.isArray(history) && history.length > 0;
    } catch (e) {
      // Keep the action available so an API error can be shown in the history view.
      this.hasSearchHistory = true;
    }
  }

  openSearchHistory() {
    document.documentElement.classList.add('mobile-search-history-open');
    this.showSearchHistoryOverlay = true;
    this.emitMobileOverlayState();
  }

  closeSearchHistory() {
    this.showSearchHistoryOverlay = false;
    document.documentElement.classList.remove('mobile-search-history-open');
    this.emitMobileOverlayState();
  }

  onSearchHistoryState(hasItems: boolean) {
    this.hasSearchHistory = hasItems;
    if (!hasItems) {
      this.closeSearchHistory();
    }
  }

  async onSearchClear() {
    this.searchQuery = '';
    this.setResults([]);
    this.setResultsCount(0);
    this.setPriorityResults(null);
    this.setNeedUpdate(false);
    this.setShowSearchResultsFlag(false);
    if (this.$route.name === 'search-results' && this.$route.query.query) {
      const language = this.navLanguage || this.$route.params.language || LANGUAGE_CODE_DEFAULT;
      if (this.mobileBookSearch && this.searchBookSlug) {
        const query = new URLSearchParams({
          slug: this.searchBookSlug,
          inBookOnly: '1',
          bookSearch: '1'
        });
        if (this.searchBookId) {
          query.set('bookId', this.searchBookId.toString());
        }
        if (typeof this.$route.query.returnTo === 'string') {
          query.set('returnTo', this.$route.query.returnTo);
        }
        await this.$router.replace(`/${language}/search?${query.toString()}`);
      } else {
        await this.$router.replace(`/${language}/search`);
      }
    }
  }

  async updateUrl() {
    const language = this.navLanguage || this.$route.params.language || LANGUAGE_CODE_DEFAULT; // language priority: left sidebar, url
    const query = this.searchQuery;
    if (!query) {
      return;
    }
    const options = {
      searchInPoem: !!this.searchInPoem,
      exact: !!this.exact,
      considerDiacritics: !!this.considerDiacritics,
      equalizeWriting: !!this.equalizeWriting
    };
    const newPath = UrlBuilderService.getSearchQueryUrl({
      language,
      query,
      bookSlug: this.searchBookSlug || undefined,
      bookId: this.searchBookId,
      inBookOnly: this.inBookSearch,
      bookSearch: this.mobileBookSearch,
      returnTo:
        this.mobileBookSearch && typeof this.$route.query.returnTo === 'string'
          ? this.$route.query.returnTo
          : undefined,
      ...options
    });
    if (this.$route.fullPath !== newPath) {
      try {
        await this.$router.push(newPath);
      } catch (error) {
        if (!(error && (error as { name?: string }).name === 'NavigationDuplicated')) {
          throw error;
        }
      }
    }
    this.setNeedUpdate(true); // see watcher in SearchResults.vue
  }

  actualizeShowAdvancedSearch() {
    this.setAdvancedSearch(
      this.exact ||
        this.considerDiacritics ||
        this.equalizeWriting ||
        this.searchInPoem ||
        this.selectedBooksCount > 0 ||
        (this.checkedCategories && this.checkedCategories.length > 0)
    );
  }

  async onInBookSearchChange() {
    this.setInBookSearch(!this.inBookSearch);
    if (this.inBookSearch) {
      this.searchInPoem = false;
      this.exact = false;
      this.considerDiacritics = false;
      this.equalizeWriting = false;
      this.setAdvancedSearch(false);
    }
    if (this.searchQuery) {
      await this.updateUrl();
    }
  }

  resetSearchSettings() {
    this.searchInPoem = false;
    this.exact = false;
    this.considerDiacritics = false;
    this.equalizeWriting = false;
    this.setInBookSearch(false);
    this.setAdvancedSearch(false);
    this.advancedSearchPanelVisible = false;
    this.showHelp = false;
    this.$store.commit('navigation/uncheckAll');
  }

  toggleAdvancedSearch() {
    this.resetMobileSheetDrag();
    if (this.mobileVisible) {
      if (!this.advancedSearchPanelVisible) {
        this.rememberMobilePanelTrigger();
        this.setAdvancedSearch(true);
      }
      this.advancedSearchPanelVisible = !this.advancedSearchPanelVisible;
      this.showHelp = false;
      this.focusActiveMobilePanel();
      return;
    }
    if (!this.advancedSearch) {
      this.rememberMobilePanelTrigger();
    }
    this.setAdvancedSearch(!this.advancedSearch);
    this.showHelp = false;
    this.focusActiveMobilePanel();
  }

  toggleHelp() {
    this.resetMobileSheetDrag();
    if (!this.showHelp) {
      this.rememberMobilePanelTrigger();
    }
    this.showHelp = !this.showHelp;
    this.focusActiveMobilePanel();
  }

  openSearchAreaPicker() {
    this.resetMobileSheetDrag();
    this.setAdvancedSearch(true);
    this.advancedSearchPanelVisible = false;
    this.showHelp = false;
    this.$emit('select-search-area');
  }

  closeMobilePanels() {
    this.resetMobileSheetDrag();
    this.advancedSearchPanelVisible = false;
    this.showHelp = false;
    this.$nextTick(() => {
      if (this.mobilePanelTrigger && document.contains(this.mobilePanelTrigger)) {
        this.mobilePanelTrigger.focus();
      }
      this.mobilePanelTrigger = null;
    });
  }

  onDocumentKeydown(event: KeyboardEvent) {
    if (!this.mobileVisible || (!this.advancedSearchPanelExpanded && !this.showHelp)) {
      return;
    }
    if (event.key === 'Escape') {
      this.closeMobilePanels();
      return;
    }
    if (event.key === 'Tab') {
      this.trapMobilePanelFocus(event);
    }
  }

  rememberMobilePanelTrigger() {
    if (!this.mobileVisible || this.mobilePanelTrigger) {
      return;
    }
    const activeElement = document.activeElement;
    if (activeElement instanceof HTMLElement && activeElement !== document.body) {
      this.mobilePanelTrigger = activeElement;
    }
  }

  focusActiveMobilePanel() {
    if (!this.mobileVisible) {
      return;
    }
    this.$nextTick(() => {
      const panel = this.getActiveMobilePanel();
      if (panel) {
        panel.focus();
      }
    });
  }

  getActiveMobilePanel(): HTMLElement | null {
    const ref = this.showHelp ? this.$refs.searchHelpPanel : this.$refs.searchOptionsPanel;
    if (!ref) {
      return null;
    }
    return ((ref as Vue).$el || ref) as HTMLElement;
  }

  trapMobilePanelFocus(event: KeyboardEvent) {
    const panel = this.getActiveMobilePanel();
    if (!panel) {
      return;
    }
    const focusable = Array.from(
      panel.querySelectorAll<HTMLElement>(
        'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
      )
    ).filter(element => element.offsetParent !== null);
    if (!focusable.length) {
      event.preventDefault();
      panel.focus();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && (document.activeElement === first || document.activeElement === panel)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }

  startMobileSheetDrag(event: PointerEvent) {
    this.mobileSheetPointerId = event.pointerId;
    this.mobileSheetDragStartY = event.clientY;
    this.mobileSheetDragging = true;
    const dragRegion = event.currentTarget as HTMLElement;
    if (dragRegion.setPointerCapture) {
      dragRegion.setPointerCapture(event.pointerId);
    }
  }

  moveMobileSheetDrag(event: PointerEvent) {
    if (this.mobileSheetDragStartY === null || this.mobileSheetPointerId !== event.pointerId) {
      return;
    }
    this.mobileSheetDragOffset = Math.max(0, event.clientY - this.mobileSheetDragStartY);
    if (this.mobileSheetDragOffset > 0 && event.cancelable) {
      event.preventDefault();
    }
  }

  endMobileSheetDrag(event: PointerEvent) {
    if (this.mobileSheetPointerId !== event.pointerId) {
      return;
    }
    const dragRegion = event.currentTarget as HTMLElement;
    if (
      dragRegion.releasePointerCapture &&
      dragRegion.hasPointerCapture &&
      dragRegion.hasPointerCapture(event.pointerId)
    ) {
      dragRegion.releasePointerCapture(event.pointerId);
    }
    if (this.mobileSheetDragOffset >= 64) {
      this.closeMobilePanels();
      return;
    }
    this.resetMobileSheetDrag();
  }

  cancelMobileSheetDrag() {
    this.resetMobileSheetDrag();
  }

  resetMobileSheetDrag() {
    this.mobileSheetDragStartY = null;
    this.mobileSheetDragOffset = 0;
    this.mobileSheetDragging = false;
    this.mobileSheetPointerId = null;
  }

  syncMobileSheetDocumentState() {
    if (!this.mobileVisible) {
      this.mobileSheetLayerVisible = false;
      document.documentElement.classList.remove('mobile-search-sheet-open');
      this.emitMobileOverlayState();
      return;
    }
    if (this.mobileSheetCloseTimer !== null) {
      window.clearTimeout(this.mobileSheetCloseTimer);
      this.mobileSheetCloseTimer = null;
    }
    if (this.advancedSearchPanelExpanded || this.showHelp) {
      this.mobileSheetLayerVisible = true;
      document.documentElement.classList.add('mobile-search-sheet-open');
      this.emitMobileOverlayState();
      return;
    }
    this.mobileSheetCloseTimer = window.setTimeout(() => {
      this.mobileSheetLayerVisible = false;
      document.documentElement.classList.remove('mobile-search-sheet-open');
      this.mobileSheetCloseTimer = null;
      this.emitMobileOverlayState();
    }, 240);
  }

  emitMobileOverlayState() {
    this.$emit(
      'mobile-overlay-change',
      this.mobileVisible && (this.mobileSheetLayerVisible || this.showSearchHistoryOverlay)
    );
  }

  /**
   * Converts object to url params string
   * @see https://stackoverflow.com/a/23639793/2393499
   */
  static objectToUrlParams(object: { [key: string]: string | (string | null)[] }) {
    return Object.entries(object)
      .map(([key, val]) => (val ? `${key}=${val}` : key))
      .join('&');
  }

  goToSearchList() {
    router.push(this.searchListUrl);
    this.setShowSearchResultsFlag(true);
  }
}
