import { Module, MutationTree } from 'vuex';
import Vue from 'vue';
import { RootState } from '@/store';
import StorageService from '@/services/StorageService';
import { LANGUAGE_CODE_DEFAULT, LIST_SCALE_DEFAULT } from '@/constants';

export interface ReaderState {
  scale: number;
  readMode: boolean;
  colorMode: 'light' | 'dark' | 'mixed';
  isTextTypesFiltersVisible: boolean;
  hideTextTypes: Array<string>;
  interfaceLanguage: string;
  catalogListScale: string;
}

const defaultState: ReaderState = {
  scale: 1,
  readMode: false,
  isTextTypesFiltersVisible: false,
  hideTextTypes: [],
  colorMode: 'light',
  interfaceLanguage: LANGUAGE_CODE_DEFAULT,
  catalogListScale: LIST_SCALE_DEFAULT
};

export const normalizeReaderState = (storedState?: Partial<ReaderState>): ReaderState => ({
  ...defaultState,
  ...(storedState || {}),
  hideTextTypes:
    storedState && Array.isArray(storedState.hideTextTypes)
      ? storedState.hideTextTypes
      : defaultState.hideTextTypes
});

const state: ReaderState = normalizeReaderState(StorageService.get('reader'));

const saveState = (state: ReaderState) => {
  StorageService.save('reader', { ...state, readMode: false });
};

const mutations: MutationTree<ReaderState> = {
  setScale(state, scale) {
    state.scale = scale;
    saveState(state);
  },

  setReadMode(state, readMode) {
    state.readMode = readMode;
    saveState(state);
  },

  setColorMode(state, colorMode) {
    state.colorMode = colorMode;
    saveState(state);
  },

  setInterfaceLanguage(state, interfaceLanguage) {
    state.interfaceLanguage = interfaceLanguage;
    saveState(state);
  },

  setCatalogListScale(state, catalogListScale) {
    Vue.set(state, 'catalogListScale', catalogListScale);
    saveState(state);
  },

  toggleTextTypesFilter(state) {
    Vue.set(state, 'isTextTypesFiltersVisible', !state.isTextTypesFiltersVisible);
    saveState(state);
  },

  setTextTypesFilterVisible(state, visible) {
    Vue.set(state, 'isTextTypesFiltersVisible', visible);
    saveState(state);
  },

  switchTextTypeFilter(state, filter) {
    state.hideTextTypes = state.hideTextTypes || [];
    const index = state.hideTextTypes.indexOf(filter);
    if (index > -1) {
      state.hideTextTypes.splice(index, 1);
    } else {
      state.hideTextTypes.push(filter);
    }
    saveState(state);
  }
};

export const module = {
  namespaced: true,
  state,
  mutations
} as Module<ReaderState, RootState>;
