
























import Vue from 'vue';
import Component from 'vue-class-component';
import router from '@/router';
import UrlBuilderService from '@/services/UrlBuilderService';
import { Prop } from 'vue-property-decorator';
import StringService from '@/services/StringService';
import IconBookCover from '@/assets/icons/book-cover.svg';
import IconGlobe from '@/assets/icons/globe.svg';
import { getTranslation } from '@/services/Translation';
import { TranslationStrings } from '@/translations/types';

interface Book {
  language?: string;
  name: string;
  authors: Array<{ name: string }>;
  slug: string;
  languages: Array<string>;
  relation_books_quantity: number;
}

@Component({
  components: { IconBookCover, IconGlobe }
})
export default class SearchPriorityBook extends Vue {
  @Prop({ required: true })
  book!: Book;

  get bookAuthors() {
    return this.book.authors.map(author => author.name).join(', ');
  }

  get bookUrl() {
    return UrlBuilderService.getBookUrl({
      language: this.book.language || router.currentRoute.params.language,
      bookSlug: this.book.slug
    });
  }

  get bookByLanguage() {
    const currentLanguage = this.book.language || router.currentRoute.params.language;
    const languages = [currentLanguage, ...(this.book.languages || [])].filter(Boolean);

    return Array.from(new Set(languages)).map(language => {
      return {
        onLanguage: StringService.capitalize(
          getTranslation(`onLanguage${StringService.capitalize(language)}` as keyof TranslationStrings)
        ),
        url: UrlBuilderService.getBookUrl({
          language,
          bookSlug: this.book.slug
        })
      };
    });
  }
}
