import { store } from '@/store';
import { ApiService } from '@/services/Api/ApiService';
import { endpoints } from '@/api-endpoints.json';
import { User } from '@/store/modules/user';

export default class UserService {
  private static readingPositionRequests: { [bookKey: string]: Promise<any> } = {};

  private static closedReadingTabs: Set<string> = new Set();

  static get bookmarksApiEnabled() {
    return process.env.VUE_APP_BOOKMARKS_API_ENABLED === 'true';
  }

  private static readingTabKey(language: string, book: string) {
    const user = store.state.user.data as User;
    const ownerKey = user.id || user.email || 'guest';
    return `${ownerKey}:${language}:${book}`;
  }

  private static enqueueReadingTabRequest(bookKey: string, request: () => Promise<any>) {
    const previous = UserService.readingPositionRequests[bookKey] || Promise.resolve();
    const queued = previous.catch(() => undefined).then(request);
    UserService.readingPositionRequests[bookKey] = queued;
    const clearQueuedRequest = () => {
      if (UserService.readingPositionRequests[bookKey] === queued) {
        delete UserService.readingPositionRequests[bookKey];
      }
    };
    queued.then(clearQueuedRequest, clearQueuedRequest);
    return queued;
  }

  static openReadingTab(language: string, book: string) {
    UserService.closedReadingTabs.delete(UserService.readingTabKey(language, book));
  }

  static getUser() {
    const endpoint = endpoints.user.currentUser;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(res => res.data.data);
  }

  static updateUser(fields: Partial<User>) {
    const endpoint = endpoints.user.currentUser;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .setBody(fields)
      .post()
      .then(res => res.data.data);
  }

  static async getUserRecentBooks() {
    const endpoint = endpoints.user.userRecentBooks;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getReadingTabs() {
    const endpoint = endpoints.user.readingTabs;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async getBookmarks() {
    if (!UserService.bookmarksApiEnabled) {
      return [];
    }
    const endpoint = endpoints.user.bookmarks;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async createBookmark(payload: {
    language: string;
    book: string;
    section: string;
    position: number;
    paragraph_anchor?: string;
    note?: string;
  }) {
    if (!UserService.bookmarksApiEnabled) {
      return null;
    }
    return new ApiService()
      .setEndpoint(endpoints.user.bookmarks)
      .setToken(store.state.auth.token)
      .setBody(payload)
      .post()
      .then(response => response.data.data);
  }

  static async updateBookmark(
    id: string | number,
    payload: {
      language: string;
      book: string;
      section: string;
      position: number;
      paragraph_anchor?: string;
      note?: string;
    }
  ) {
    if (!UserService.bookmarksApiEnabled) {
      return null;
    }
    return new ApiService()
      .setEndpoint(`${endpoints.user.bookmarks}/${id}`)
      .setToken(store.state.auth.token)
      .setBody(payload)
      .put()
      .then(response => response.data.data);
  }

  static async removeBookmark(id: string | number) {
    if (!UserService.bookmarksApiEnabled) {
      return null;
    }
    return new ApiService()
      .setEndpoint(`${endpoints.user.bookmarks}/${id}`)
      .setToken(store.state.auth.token)
      .delete()
      .then(response => response.data.data);
  }

  static async saveReadingPosition(payload: {
    language: string;
    book: string;
    section: string;
    position: number;
    section_positions?: { [link: string]: number };
  }) {
    const bookKey = UserService.readingTabKey(payload.language, payload.book);
    if (UserService.closedReadingTabs.has(bookKey)) {
      return undefined;
    }
    const endpoint = endpoints.user.readingTabs;
    const token = store.state.auth.token;
    return UserService.enqueueReadingTabRequest(bookKey, () =>
      new ApiService()
        .setEndpoint(endpoint)
        .setToken(token)
        .setBody(payload)
        .post()
        .then(response => response.data.data)
    );
  }

  static saveReadingPositionOnPageHide(payload: {
    language: string;
    book: string;
    section: string;
    position: number;
    section_positions?: { [link: string]: number };
  }) {
    const bookKey = UserService.readingTabKey(payload.language, payload.book);
    if (UserService.closedReadingTabs.has(bookKey)) {
      return Promise.resolve(undefined);
    }
    const headers: { [name: string]: string } = {
      'Content-Type': 'application/json'
    };
    if (store.state.auth.token) {
      headers['Api-Authorization'] = store.state.auth.token;
    }
    return fetch(`${process.env.VUE_APP_API_URL}${endpoints.user.readingTabs}`, {
      method: 'POST',
      headers,
      credentials: 'include',
      keepalive: true,
      body: JSON.stringify(payload)
    }).catch(() => undefined);
  }

  static async closeReadingTab(language: string, book: string) {
    const bookKey = UserService.readingTabKey(language, book);
    UserService.closedReadingTabs.add(bookKey);
    const endpoint = endpoints.user.readingTabs;
    const token = store.state.auth.token;
    return UserService.enqueueReadingTabRequest(bookKey, () =>
      new ApiService()
        .setEndpoint(endpoint)
        .setToken(token)
        .setParams({ language, book })
        .delete()
        .then(response => response.data.data)
    );
  }
}
