









































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import { Bookmark } from '@/store/modules/bookmarks';
import IconBookmark from '@/assets/icons/bookmark.svg';
import IconCross from '@/assets/icons/cross.svg';
import { getTranslation } from '@/services/Translation';

@Component({ components: { IconBookmark, IconCross } })
export default class MobileBookmarks extends Vue {
  @Prop({ required: true })
  bookmarks!: Array<Bookmark>;

  getTranslation = getTranslation;

  languageLabel(bookmark: Bookmark) {
    const language = bookmark.language.toUpperCase();
    return language === 'ST' ? 'SAN' : language;
  }
}
