











































import Vue from 'vue';
import Component from 'vue-class-component';
import Overlay from '@/components/ui/Overlay.vue';
import { State } from 'vuex-class';

@Component({
  components: { Overlay }
})
export default class SettingsExample extends Vue {
  @State('scale', { namespace: 'reader' })
  scale!: number;

  @State('hideTextTypes', { namespace: 'reader' })
  hideTextTypes!: Array<string>;

  isTextTypeVisible(code: string) {
    return !this.hideTextTypes || !this.hideTextTypes.includes(code);
  }
}
