




















import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import Checkbox from '@/components/ui/Checkbox.vue';
import NavItemIcon from '@/components/nav/NavItemIcon.vue';
import NavItemText from '@/components/nav/NavItemText.vue';
import NavItemEntriesCount from '@/components/nav/NavItemEntriesCount.vue';
import { State } from 'vuex-class';
import { LIST_SCALE_AUTO, LIST_SCALE_TABLET } from '@/constants';

@Component({
  components: { NavItemEntriesCount, Checkbox, NavItemIcon, NavItemText }
})
export default class NavItemLink extends Vue {
  LIST_SCALE_AUTO = LIST_SCALE_AUTO;

  LIST_SCALE_TABLET = LIST_SCALE_TABLET;

  @Prop({ required: true })
  highlight!: boolean;

  @Prop({ required: true })
  searchMatch!: boolean;

  @Prop({ required: true })
  to!: string;

  @Prop({ required: true })
  text!: string;

  @Prop({ required: true })
  offset!: number;

  @Prop({ required: true })
  primary!: boolean;

  @Prop({ required: true })
  checked!: boolean;

  @Prop({ required: false })
  showEntriesCount?: boolean;

  @Prop({ required: false })
  entriesCount?: number;

  @State('catalogListScale', { namespace: 'reader' })
  catalogListScale!: string;

  onNavigate() {
    this.$nextTick(() => {
      this.$root.$emit('reader-link-selected', { link: this.to, name: this.text });
    });
  }
}
