import { AnyNavEntity, Books, ListType } from '@/services/Navigation/types';
import { LIST_TYPE_DEFAULT } from '@/constants';

export default class Helpers {
  public static collapseAll<T extends AnyNavEntity>(array: Array<T>): Array<T> {
    return array.map(item => ({ ...item, expanded: false }));
  }

  public static collapseBooks(origin: Books) {
    const books = { ...origin };
    for (let slug in books) {
      books[slug].expanded = false;
    }
    return books;
  }

  public static checkAll<T extends AnyNavEntity>(array: Array<T>): Array<T> {
    return array.map(item => ({ ...item, checked: true, partiallyChecked: false }));
  }

  public static checkBooks(origin: Books) {
    const books = { ...origin };
    for (let slug in books) {
      books[slug].checked = true;
      books[slug].partiallyChecked = false;
    }
    return books;
  }

  public static checkBookSections(origin: Books) {
    const books = { ...origin };
    for (let slug in books) {
      books[slug].children = books[slug].children.map(one => ({
        ...one,
        checked: true,
        partiallyChecked: false
      }));
    }
    return books;
  }

  public static uncheckAll<T extends AnyNavEntity>(array: Array<T>): Array<T> {
    return array.map(item => ({ ...item, checked: false, partiallyChecked: false }));
  }

  public static uncheckBooks(origin: Books) {
    const books = { ...origin };
    for (let slug in books) {
      books[slug].checked = false;
      books[slug].partiallyChecked = false;
    }
    return books;
  }

  public static uncheckBookSections(origin: Books) {
    const books = { ...origin };
    for (let slug in books) {
      for (let j in books[slug].children) {
        books[slug].children = books[slug].children.map(one => ({
          ...one,
          checked: false,
          partiallyChecked: false
        }));
      }
    }
    return books;
  }

  public static getParents(array: Array<{ [key: string]: any }>, startIndex: number) {
    const parents: Array<{ [key: string]: any }> = [];
    const initialDepth = array[startIndex].depth;
    let previousDepth = initialDepth;
    if (previousDepth === 0) {
      return parents;
    }
    for (let i = startIndex; i >= 0; i--) {
      const item = array[i];
      // we need to update each item with less depth on each level of depth
      if (item.depth < initialDepth && item.depth < previousDepth) {
        parents.push(item);
        previousDepth = item.depth;
      }
      // if current item depth is zero - this is a root item, no parents left
      if (item.depth === 0) {
        return parents;
      }
    }
    return parents;
  }

  public static updateParents(
    array: Array<{ [key: string]: any }>,
    startIndex: number,
    callback: (item: { [key: string]: any }) => { [key: string]: any }
  ) {
    const initialDepth = array[startIndex].depth;
    let previousDepth = initialDepth;
    if (previousDepth === 0) {
      return array;
    }
    for (let i = startIndex; i >= 0; i--) {
      const item = array[i];
      // we need to update each item with less depth on each level of depth
      if (item.depth < initialDepth && item.depth < previousDepth) {
        array[i] = Object.assign(array[i], callback(item));
        previousDepth = item.depth;
      }
      // if current item depth is zero - this is a root item, no parents left
      if (item.depth === 0) {
        return array;
      }
    }
    return array;
  }

  public static updateChildren(
    array: Array<{ [key: string]: any }>,
    startIndex: number,
    callback: (item: { [key: string]: any }) => { [key: string]: any }
  ) {
    const initialDepth = array[startIndex].depth;
    for (let i = startIndex; i < array.length; i++) {
      const item = array[i];
      // if current item has equal or greater depth then the initial one - then there is no children left
      if (item.depth <= initialDepth && i !== startIndex) {
        return array;
      }
      // we need to update all items with greater depth
      if (item.depth > initialDepth) {
        array[i] = Object.assign(array[i], callback(item));
      }
    }
    return array;
  }

  public static *flatten(
    array: Array<{ [key: string]: any }>,
    childrenPropName: string,
    depth: number = 0,
    parentId: number | null = null
  ): Generator<{ [key: string]: any }> {
    for (const item of array) {
      const isParent = !!item[childrenPropName] && item[childrenPropName].length > 0;
      const id = item.id || item.code; // todo: this workaround for book sections without ID
      yield {
        ...item,
        id,
        depth,
        isParent,
        parentId
      };
      if (isParent) {
        yield* Helpers.flatten(item[childrenPropName], childrenPropName, depth + 1, item.id || item.code);
      }
    }
  }

  public static parseListTypeFromUrl(url: string): ListType {
    const slug = url.split('/')[2];
    return slug && ['categories', 'authors', 'books'].includes(slug) ? (slug as ListType) : LIST_TYPE_DEFAULT;
  }
}
