const RELATED_TRAIL_QUERY = 'relatedTrail';
const MAX_RELATED_TRAIL_LENGTH = 12;

type QueryValue = string | Array<string | null> | null | undefined;

export default class RelatedNavigationService {
  static createTargetUrl(targetUrl: string, currentUrl: string, trailValue?: QueryValue) {
    const trail = RelatedNavigationService.parseTrail(trailValue);
    const sourceUrl = RelatedNavigationService.withTrail(currentUrl, []);
    if (sourceUrl && trail[trail.length - 1] !== sourceUrl) {
      trail.push(sourceUrl);
    }
    return RelatedNavigationService.withTrail(targetUrl, trail.slice(-MAX_RELATED_TRAIL_LENGTH));
  }

  static getPreviousUrl(trailValue?: QueryValue) {
    const trail = RelatedNavigationService.parseTrail(trailValue);
    const previousUrl = trail.pop();
    return previousUrl ? RelatedNavigationService.withTrail(previousUrl, trail) : '';
  }

  static hasPrevious(trailValue?: QueryValue) {
    return RelatedNavigationService.parseTrail(trailValue).length > 0;
  }

  private static parseTrail(value?: QueryValue): Array<string> {
    const raw = Array.isArray(value) ? value[0] : value;
    if (!raw || typeof raw !== 'string') {
      return [];
    }
    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed)
        ? parsed.filter(item => typeof item === 'string' && item.startsWith('/') && !item.startsWith('//'))
        : [];
    } catch (error) {
      return [];
    }
  }

  private static withTrail(url: string, trail: Array<string>) {
    if (!url || !url.startsWith('/') || url.startsWith('//')) {
      return '';
    }
    const hashIndex = url.indexOf('#');
    const hash = hashIndex >= 0 ? url.slice(hashIndex) : '';
    const withoutHash = hashIndex >= 0 ? url.slice(0, hashIndex) : url;
    const queryIndex = withoutHash.indexOf('?');
    const path = queryIndex >= 0 ? withoutHash.slice(0, queryIndex) : withoutHash;
    const query = new URLSearchParams(queryIndex >= 0 ? withoutHash.slice(queryIndex + 1) : '');
    if (trail.length) {
      query.set(RELATED_TRAIL_QUERY, JSON.stringify(trail));
    } else {
      query.delete(RELATED_TRAIL_QUERY);
    }
    const queryString = query.toString();
    return `${path}${queryString ? `?${queryString}` : ''}${hash}`;
  }
}
