























































































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Watch } from 'vue-property-decorator';
import BooksService from '@/services/Api/BooksService';
import Loader from '@/components/ui/Loader.vue';
import UrlBuilderService from '@/services/UrlBuilderService';
import * as Book from '@/services/Api/BooksService/Book.types';
import DownloadIcon from '@/assets/icons/download.svg';
import SearchIcon from '@/assets/icons/zoom.svg';
import { Getter } from 'vuex-class';
import { Book as NavigationBook } from '@/services/Navigation/types';
import BooksWithTranslations from '@/components/BooksWithTranslations.vue';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { BooksWithTranslations, Loader, DownloadIcon, SearchIcon }
})
export default class BookCover extends Vue {
  book: null | Book.Content = null;

  loading: boolean = false;

  getTranslation = getTranslation;

  @Getter('currentBook', { namespace: 'navigation' })
  navigationBook?: NavigationBook;

  get authors() {
    return this.book ? this.book.authors.map(author => author.name).join(', ') : '';
  }

  get continueReadingUrl() {
    if (!this.book) {
      return '';
    }
    const validateSectionUrl = (url: string) => {
      if (!(url && this.navigationBook && this.navigationBook.children.length)) {
        return url;
      }
      const sectionSlug = url
        .split('?')[0]
        .split('/')
        .filter(Boolean)
        .pop();
      if (this.navigationBook.children.some(section => section.slug === sectionSlug)) {
        return url;
      }
      const firstValidSection =
        this.navigationBook.children.find(section => !section.is_parent) || this.navigationBook.children[0];
      return firstValidSection ? this.getFirstBookSectionLink(firstValidSection.slug) : '';
    };
    const bookKey = `${this.$route.params.language}:${this.$route.params.book}`;
    const savedTab = this.$store.state.tabs.list.find(
      (tab: { bookKey?: string; link?: string }) => tab.bookKey === bookKey && tab.link
    );
    if (savedTab && savedTab.link && savedTab.link.split('?')[0] !== this.$route.path) {
      return validateSectionUrl(savedTab.link);
    }
    return validateSectionUrl(this.book.firstSectionUrl || '');
  }

  get bookSearchUrl() {
    const query = new URLSearchParams({
      slug: this.$route.params.book,
      inBookOnly: '1',
      bookSearch: '1',
      returnTo: this.$route.fullPath
    });
    if (this.navigationBook && this.navigationBook.id) {
      query.set('bookId', this.navigationBook.id.toString());
    }
    return `/${this.$route.params.language}/search?${query.toString()}`;
  }

  async mounted() {
    await this.fetchBook();
    this.updateTabName();
  }

  @Watch('$route')
  async onRouteChange() {
    await this.fetchBook();
    this.updateTabName();
  }

  updateTabName() {
    const bookName = this.navigationBook
      ? this.navigationBook.name
      : this.book
      ? this.book.name
      : getTranslation('book');
    this.$store.commit('tabs/updateActiveTabDetails', {
      name: bookName,
      bookName
    });
  }

  async fetchBook() {
    if (this.$route.params.book) {
      this.loading = true;
      this.book = await BooksService.getBookCover(this.$route.params.language, this.$route.params.book);
      if (this.book) {
        if (this.book.other_publications) {
          this.book.other_publications = this.prepareTranslations(this.book.other_publications);
        }
        if (this.book.related_books) {
          this.book.related_books = this.prepareTranslations(this.book.related_books);
        }
        if (this.book.first_section_slug) {
          this.book.firstSectionUrl = this.getFirstBookSectionLink(this.book.first_section_slug);
        }
      }
      this.loading = false;
    }
  }

  getFirstBookSectionLink(slug: string) {
    return UrlBuilderService.getBookSectionUrl({
      language: this.$route.params.language,
      categorySlug: this.$route.params.category,
      authorSlug: this.$route.params.author,
      bookSlug: this.$route.params.book,
      bookSectionSlug: slug
    });
  }

  prepareTranslations(books: Array<any>) {
    return books.map(publication => ({
      ...publication,
      translations: publication.translations.map((translation: Book.Translation) => ({
        ...translation,
        url: UrlBuilderService.getBookUrl({
          language: translation.lang,
          categorySlug: this.$route.params.category,
          bookSlug: publication.slug
        })
      }))
    }));
  }
}
