export default class StringService {
  /**
   * Capitalize first letter of a string
   * @param str
   * @see https://stackoverflow.com/a/3291856
   */
  static capitalize(str: string) {
    return str.charAt(0).toUpperCase() + str.slice(1);
  }

  static replaceAll(string: string, search: string, replace: string) {
    return string.split(search).join(replace);
  }

  /**
   * https://stackoverflow.com/a/1714899/2393499
   * @param obj
   */
  static objectToQueryString(obj: { [key: string]: any }) {
    const str = [];
    for (const key in obj)
      if (obj.hasOwnProperty(key)) {
        str.push(encodeURIComponent(key) + '=' + encodeURIComponent(obj[key].toString()));
      }
    return str.join('&');
  }
}
