
























import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import router from '@/router';
import UrlBuilderService from '@/services/UrlBuilderService';
import StringService from '@/services/StringService';
import Collapsible from '@/components/ui/Collapsible.vue';
import BooksWithTranslations from '@/components/BooksWithTranslations.vue';
import { getTranslation } from '@/services/Translation';
import { TranslationStrings } from '@/translations/types';

interface Author {
  name: string;
  slug: string;
  statistics: {
    all: number;
    languages: Array<{ lang: string; count: number }>;
    books: Array<{ name: string; slug: string; translations: Array<{ lang: string; short_name: string }> }>;
  };
}

@Component({
  components: { BooksWithTranslations, Collapsible }
})
export default class SearchPriorityAuthor extends Vue {
  @Prop({ required: true })
  author!: Author;

  getTranslation = getTranslation;

  get authorUrl() {
    return UrlBuilderService.getAuthorUrl({
      language: router.currentRoute.params.language,
      authorSlug: this.author.slug
    });
  }

  get authorBooks() {
    return Object.values(this.author.statistics.books).map(book => ({
      name: book.name,
      translations: book.translations.map(translation => ({
        ...translation,
        url: UrlBuilderService.getBookUrl({
          language: translation.lang,
          bookSlug: book.slug
        })
      }))
    }));
  }

  get booksByLanguage() {
    return this.author.statistics.languages.map(language => ({
      ...language,
      onLanguage: StringService.capitalize(
        getTranslation(`onLanguage${StringService.capitalize(language.lang)}` as keyof TranslationStrings)
      )
    }));
  }
}
